use super::{Client,errors::{DiscordError,Result}};
use std::path::{Path,PathBuf};
use windows::{core::PWSTR,Win32::{Foundation::{CloseHandle,HANDLE},System::{Diagnostics::ToolHelp::*,Threading::{OpenProcess,PROCESS_QUERY_LIMITED_INFORMATION,QueryFullProcessImageNameW,PROCESS_NAME_WIN32,OpenProcessToken}},Security::{GetTokenInformation,TokenIntegrityLevel,TOKEN_QUERY,TOKEN_MANDATORY_LABEL,GetSidSubAuthorityCount,GetSidSubAuthority}}};
struct Handle(HANDLE);impl Drop for Handle{fn drop(&mut self){unsafe{let _=CloseHandle(self.0);}}}
pub fn path(pid:u32)->Option<PathBuf>{unsafe{let process=Handle(OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,false,pid).ok()?);let mut value=vec![0u16;32768];let mut len=value.len()as u32;QueryFullProcessImageNameW(process.0,PROCESS_NAME_WIN32,PWSTR(value.as_mut_ptr()),&mut len).ok()?;Some(PathBuf::from(String::from_utf16_lossy(&value[..len as usize])))}}
pub fn integrity(pid:u32)->Option<u32>{unsafe{let process=Handle(OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,false,pid).ok()?);let mut token=HANDLE::default();OpenProcessToken(process.0,TOKEN_QUERY,&mut token).ok()?;let token=Handle(token);let mut len=0u32;let _=GetTokenInformation(token.0,TokenIntegrityLevel,None,0,&mut len);if len==0||len>65536{return None;}let mut buffer=vec![0u64;(len as usize+7)/8];GetTokenInformation(token.0,TokenIntegrityLevel,Some(buffer.as_mut_ptr().cast()),len,&mut len).ok()?;let label=&*(buffer.as_ptr().cast::<TOKEN_MANDATORY_LABEL>());let count=*GetSidSubAuthorityCount(label.Label.Sid);if count==0{return None;}Some(*GetSidSubAuthority(label.Label.Sid,count as u32-1))}}
fn roots(folder:&str)->Vec<PathBuf>{["LOCALAPPDATA","PROGRAMFILES","PROGRAMFILES(X86)"].into_iter().filter_map(std::env::var_os).map(|root|PathBuf::from(root).join(folder)).collect()}
fn verified(path:&Path,roots:&[PathBuf],exe:&str)->bool{
 path.file_name().is_some_and(|name|name.to_string_lossy().eq_ignore_ascii_case(exe))&&path.parent().is_some_and(|parent|parent.file_name().is_some_and(|name|name.to_string_lossy().starts_with("app-"))&&parent.parent().is_some_and(|root|roots.iter().any(|known|root.to_string_lossy().eq_ignore_ascii_case(&known.to_string_lossy()))))
}
pub fn scan()->Result<Vec<Client>>{unsafe{
 let definitions=[("stable","Discord","Discord.exe"),("ptb","DiscordPTB","DiscordPTB.exe"),("canary","DiscordCanary","DiscordCanary.exe")];
 let mut clients:Vec<_>=definitions.iter().map(|(id,folder,exe)|{let installed=roots(folder).iter().any(|root|std::fs::read_dir(root).ok().is_some_and(|dirs|dirs.filter_map(|e|e.ok()).any(|e|e.file_name().to_string_lossy().starts_with("app-")&&e.path().join(exe).is_file())));Client{variant:(*id).into(),installed,running:false,pids:vec![],privilege_compatible:false}}).collect();
 let snapshot=Handle(CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0).map_err(|_|DiscordError::new("detection","Не удалось получить список процессов Discord."))?);
 let mut entry=PROCESSENTRY32W{dwSize:std::mem::size_of::<PROCESSENTRY32W>()as u32,..Default::default()};
 if Process32FirstW(snapshot.0,&mut entry).is_ok(){loop{let end=entry.szExeFile.iter().position(|c|*c==0).unwrap_or(entry.szExeFile.len());let name=String::from_utf16_lossy(&entry.szExeFile[..end]);for(index,(_,folder,exe))in definitions.iter().enumerate(){if name.eq_ignore_ascii_case(exe){if let Some(path)=path(entry.th32ProcessID){if verified(&path,&roots(folder),exe){clients[index].pids.push(entry.th32ProcessID);}}}}if Process32NextW(snapshot.0,&mut entry).is_err(){break;}}}
 let own=integrity(windows::Win32::System::Threading::GetCurrentProcessId());for client in &mut clients{client.pids.sort_unstable();client.running=!client.pids.is_empty();client.installed|=client.running;client.privilege_compatible=client.running&&own.is_some_and(|own|client.pids.iter().all(|pid|integrity(*pid).is_some_and(|other|other<=own)));}Ok(clients)
}}
#[cfg(test)]mod tests{use super::*;
 #[test]fn verifies_executable_and_installation_root(){let roots=vec![PathBuf::from(r"C:\Users\test\AppData\Local\Discord")];assert!(verified(Path::new(r"C:\Users\test\AppData\Local\Discord\app-1.0.0\Discord.exe"),&roots,"Discord.exe"));for path in [r"C:\Games\Discord\app-1.0.0\Discord.exe",r"C:\Users\test\AppData\Local\Discord\app-1.0.0\DiscordPTB.exe",r"C:\Users\test\AppData\Local\Discord\Discord.exe"]{assert!(!verified(Path::new(path),&roots,"Discord.exe"));}}
}
